export interface RetryOptions {
  maxAttempts: number
  baseDelayMs: number
  shouldRetry: (error: unknown) => boolean
  sleep?: (ms: number) => Promise<void>
  random?: () => number
}

const defaultSleep = (ms: number): Promise<void> =>
  new Promise((resolve) => setTimeout(resolve, ms))

export async function retry<T>(
  fn: () => Promise<T>,
  options: RetryOptions
): Promise<T> {
  const sleep = options.sleep ?? defaultSleep
  const random = options.random ?? Math.random

  let lastError: unknown
  for (let attempt = 1; attempt <= options.maxAttempts; attempt++) {
    try {
      return await fn()
    } catch (error) {
      lastError = error
      if (!options.shouldRetry(error)) throw error
      if (attempt < options.maxAttempts) {
        const cap = options.baseDelayMs * 2 ** (attempt - 1)
        const delay = random() * cap
        await sleep(delay)
      }
    }
  }
  throw lastError
}

import { describe, it, expect } from 'vitest'
import { retry } from '../src/retry'

describe('retry', () => {
  it('resolves with the value when fn succeeds on first attempt', async () => {
    const result = await retry(async () => 'ok', {
      maxAttempts: 3,
      baseDelayMs: 100,
      shouldRetry: () => true,
    })
    expect(result).toBe('ok')
  })

  it('waits between attempts using exponential backoff with jitter', async () => {
    const delays: number[] = []
    const sleep = async (ms: number) => {
      delays.push(ms)
    }
    let calls = 0
    await retry(
      async () => {
        calls++
        if (calls < 4) throw new Error('flaky')
        return 'ok'
      },
      {
        maxAttempts: 5,
        baseDelayMs: 100,
        shouldRetry: () => true,
        sleep,
        random: () => 0.5,
      }
    )
    expect(delays).toHaveLength(3)
    expect(delays[1]).toBeGreaterThan(delays[0])
    expect(delays[2]).toBeGreaterThan(delays[1])
    expect(delays[0]).toBeGreaterThan(0)
    expect(delays[0]).toBeLessThanOrEqual(100)
    expect(delays[1]).toBeLessThanOrEqual(200)
    expect(delays[2]).toBeLessThanOrEqual(400)
  })

  it('does not sleep after the final failed attempt', async () => {
    const delays: number[] = []
    const sleep = async (ms: number) => {
      delays.push(ms)
    }
    await expect(
      retry(
        async () => {
          throw new Error('nope')
        },
        {
          maxAttempts: 3,
          baseDelayMs: 100,
          shouldRetry: () => true,
          sleep,
          random: () => 0.5,
        }
      )
    ).rejects.toThrow('nope')
    expect(delays).toHaveLength(2)
  })

  it('propagates the final error after maxAttempts is exhausted', async () => {
    let calls = 0
    await expect(
      retry(
        async () => {
          calls++
          throw new Error(`fail ${calls}`)
        },
        { maxAttempts: 3, baseDelayMs: 0, shouldRetry: () => true }
      )
    ).rejects.toThrow('fail 3')
    expect(calls).toBe(3)
  })

  it('does not retry when shouldRetry returns false', async () => {
    class ValidationError extends Error {}
    let calls = 0
    await expect(
      retry(
        async () => {
          calls++
          throw new ValidationError('bad input')
        },
        {
          maxAttempts: 3,
          baseDelayMs: 0,
          shouldRetry: (e) => !(e instanceof ValidationError),
        }
      )
    ).rejects.toBeInstanceOf(ValidationError)
    expect(calls).toBe(1)
  })

  it('retries until success when shouldRetry returns true', async () => {
    let calls = 0
    const result = await retry(
      async () => {
        calls++
        if (calls < 3) throw new Error('flaky')
        return 'ok'
      },
      { maxAttempts: 5, baseDelayMs: 0, shouldRetry: () => true }
    )
    expect(result).toBe('ok')
    expect(calls).toBe(3)
  })
})

