          return 'ok'
        },
        {
          maxAttempts: 5,
          baseDelayMs: 100,
          shouldRetry: () => true,
          sleep,
          random: () => 0.5,
        }
      )
      expect(result).toBe('ok')
      expect(delays).toEqual([250, 250])
    })

    it('does not apply jitter on top of retryAfterMs', async () => {
      class ThrottledError extends Error {
        retryAfterMs = 500
      }
      const delays: number[] = []
      const sleep = async (ms: number) => {
        delays.push(ms)
      }
      await expect(
        retry(
          async () => {
            throw new ThrottledError('busy')
          },
          {
            maxAttempts: 3,
            baseDelayMs: 100,
            shouldRetry: () => true,
            sleep,
            random: () => 0.1,
          }
        )
      ).rejects.toThrow('busy')
      expect(delays).toEqual([500, 500])
    })

    it('falls back to exponential backoff per attempt when retryAfterMs is missing or invalid', async () => {
      const delays: number[] = []
      const sleep = async (ms: number) => {
        delays.push(ms)
      }
      const errors = [
        Object.assign(new Error('a'), { retryAfterMs: 250 }),
        new Error('b'),
        Object.assign(new Error('c'), { retryAfterMs: -1 }),
        Object.assign(new Error('d'), { retryAfterMs: 'soon' }),
        Object.assign(new Error('e'), { retryAfterMs: Infinity }),
      ]
      let calls = 0
      await expect(
        retry(
          async () => {
            throw errors[calls++]
          },
          {
            maxAttempts: 5,
            baseDelayMs: 100,
            shouldRetry: () => true,
            sleep,
            random: () => 0.5,
          }
        )
