      // attempt 3 (retryAfterMs=-1, invalid): 0.5 * 100 * 2^2 = 200
      // attempt 4 (retryAfterMs='soon', invalid): 0.5 * 100 * 2^3 = 400
      // attempt 5 is the last attempt — no sleep
