      const sleep = async (ms: number) => {
        delays.push(ms)
      }
      let calls = 0
      const result = await retry(
        async () => {
          calls++
          if (calls < 2) {
            throw Object.assign(new Error('rate'), { retryAfterMs: 0 })
          }
          return 'ok'
        },
        {
          maxAttempts: 3,
          baseDelayMs: 100,
          shouldRetry: () => true,
          sleep,
          random: () => 0.5,
        }
      )
      expect(result).toBe('ok')
      expect(delays).toEqual([0])
    })
  })
})

